static const unsigned GPRDecoderTable[] = {
        RISCV_X0,  RISCV_X1,  RISCV_X2,  RISCV_X3,
        RISCV_X4,  RISCV_X5,  RISCV_X6,  RISCV_X7,
        RISCV_X8,  RISCV_X9,  RISCV_X10, RISCV_X11,
